insert into public.form_templates (name, description, category, is_system, schema) values
  ('RSVP', 'Collect yes/no replies and guest counts for an event.', 'events', true, '{"schemaVersion":1,"title":"RSVP","description":"Let us know if you can make it.","layout":"conversational","sections":[{"id":"s1","title":"Your RSVP","pageBreakAfter":false}],"questions":[{"id":"name","type":"name","sectionId":"s1","label":"Full name","required":true,"config":{},"validation":{},"rules":[]},{"id":"email","type":"email","sectionId":"s1","label":"Email","required":true,"config":{},"validation":{},"rules":[]},{"id":"attending","type":"yes_no","sectionId":"s1","label":"Will you be attending?","required":true,"config":{},"validation":{},"rules":[]},{"id":"guests","type":"number","sectionId":"s1","label":"Number of guests (including you)","required":true,"config":{"allowDecimals":false},"validation":{"min":1,"max":10},"rules":[{"id":"r1","combinator":"and","conditions":[{"questionId":"attending","operator":"equals","value":true}],"action":{"type":"show"}}]},{"id":"dietary","type":"long_text","sectionId":"s1","label":"Any dietary restrictions?","required":false,"config":{},"validation":{},"rules":[{"id":"r2","combinator":"and","conditions":[{"questionId":"attending","operator":"equals","value":true}],"action":{"type":"show"}}]}],"completionScreen":{"title":"Thank you!","message":"Your response has been received."}}'::jsonb),
  ('Order form', 'Take simple product orders with quantity and delivery details.', 'sales', true, '{"schemaVersion":1,"title":"Order form","description":"Place your order below.","layout":"classic","sections":[{"id":"s1","title":"Order details","pageBreakAfter":false}],"questions":[{"id":"name","type":"name","sectionId":"s1","label":"Full name","required":true,"config":{},"validation":{},"rules":[]},{"id":"email","type":"email","sectionId":"s1","label":"Email","required":true,"config":{},"validation":{},"rules":[]},{"id":"product","type":"dropdown","sectionId":"s1","label":"Product","required":true,"config":{},"validation":{},"rules":[],"options":[{"id":"o1","label":"Small","value":"small"},{"id":"o2","label":"Medium","value":"medium"},{"id":"o3","label":"Large","value":"large"}]},{"id":"quantity","type":"number","sectionId":"s1","label":"Quantity","required":true,"config":{"allowDecimals":false},"validation":{"min":1},"rules":[]},{"id":"address","type":"long_text","sectionId":"s1","label":"Delivery address","required":true,"config":{},"validation":{},"rules":[]},{"id":"notes","type":"long_text","sectionId":"s1","label":"Special instructions","required":false,"config":{},"validation":{},"rules":[]}],"completionScreen":{"title":"Order received!","message":"We''ll be in touch to confirm."}}'::jsonb),
  ('Contact us', 'A short contact form for a website footer or landing page.', 'enquiry', true, '{"schemaVersion":1,"title":"Contact us","description":"Send us a message and we''ll reply soon.","layout":"classic","sections":[{"id":"s1","title":"Message","pageBreakAfter":false}],"questions":[{"id":"name","type":"name","sectionId":"s1","label":"Name","required":true,"config":{},"validation":{},"rules":[]},{"id":"email","type":"email","sectionId":"s1","label":"Email","required":true,"config":{},"validation":{},"rules":[]},{"id":"subject","type":"short_text","sectionId":"s1","label":"Subject","required":true,"config":{},"validation":{"maxLength":120},"rules":[]},{"id":"message","type":"long_text","sectionId":"s1","label":"Message","required":true,"config":{},"validation":{"maxLength":1500},"rules":[]}],"completionScreen":{"title":"Message sent","message":"Thanks \u2014 we''ll get back to you."}}'::jsonb),
  ('Course registration', 'Register students for a course or workshop session.', 'education', true, '{"schemaVersion":1,"title":"Course registration","description":"Reserve your seat in an upcoming session.","layout":"conversational","sections":[{"id":"s1","title":"Registration","pageBreakAfter":false}],"questions":[{"id":"name","type":"name","sectionId":"s1","label":"Full name","required":true,"config":{},"validation":{},"rules":[]},{"id":"email","type":"email","sectionId":"s1","label":"Email","required":true,"config":{},"validation":{},"rules":[]},{"id":"session","type":"single_choice","sectionId":"s1","label":"Which session?","required":true,"config":{},"validation":{},"rules":[],"options":[{"id":"o1","label":"Morning","value":"morning"},{"id":"o2","label":"Afternoon","value":"afternoon"},{"id":"o3","label":"Evening","value":"evening"}]},{"id":"experience","type":"opinion_scale","sectionId":"s1","label":"How would you rate your experience level?","required":false,"config":{"start":0,"end":10,"leftLabel":"Beginner","rightLabel":"Expert"},"validation":{},"rules":[]},{"id":"goals","type":"long_text","sectionId":"s1","label":"What do you hope to get out of this course?","required":false,"config":{},"validation":{},"rules":[]}],"completionScreen":{"title":"You''re registered!","message":"We''ll send joining details by email."}}'::jsonb),
  ('Volunteer signup', 'Recruit volunteers and capture availability and interests.', 'nonprofit', true, '{"schemaVersion":1,"title":"Volunteer signup","description":"Thanks for offering your time.","layout":"conversational","sections":[{"id":"s1","title":"About you","pageBreakAfter":false}],"questions":[{"id":"name","type":"name","sectionId":"s1","label":"Full name","required":true,"config":{},"validation":{},"rules":[]},{"id":"email","type":"email","sectionId":"s1","label":"Email","required":true,"config":{},"validation":{},"rules":[]},{"id":"phone","type":"phone","sectionId":"s1","label":"Phone","required":false,"config":{},"validation":{},"rules":[]},{"id":"interests","type":"multiple_choice","sectionId":"s1","label":"Which areas interest you?","required":true,"config":{},"validation":{},"rules":[],"options":[{"id":"o1","label":"Events","value":"events"},{"id":"o2","label":"Fundraising","value":"fundraising"},{"id":"o3","label":"Outreach","value":"outreach"},{"id":"o4","label":"Admin support","value":"admin"}]},{"id":"availability","type":"dropdown","sectionId":"s1","label":"Typical availability","required":true,"config":{},"validation":{},"rules":[],"options":[{"id":"o1","label":"Weekday mornings","value":"weekday_am"},{"id":"o2","label":"Weekday evenings","value":"weekday_pm"},{"id":"o3","label":"Weekends","value":"weekend"}]}],"completionScreen":{"title":"Thank you!","message":"Someone from our team will be in touch."}}'::jsonb),
  ('Rental application', 'Screen applicants for a rental property.', 'real_estate', true, '{"schemaVersion":1,"title":"Rental application","description":"Apply to rent this property.","layout":"conversational","sections":[{"id":"about","title":"About you","pageBreakAfter":true},{"id":"hist","title":"History","pageBreakAfter":false}],"questions":[{"id":"name","type":"name","sectionId":"about","label":"Full name","required":true,"config":{},"validation":{},"rules":[]},{"id":"email","type":"email","sectionId":"about","label":"Email","required":true,"config":{},"validation":{},"rules":[]},{"id":"phone","type":"phone","sectionId":"about","label":"Phone","required":true,"config":{},"validation":{},"rules":[]},{"id":"move_in","type":"date","sectionId":"about","label":"Preferred move-in date","required":true,"config":{},"validation":{},"rules":[]},{"id":"income","type":"currency","sectionId":"hist","label":"Monthly income","required":true,"config":{"currency":"USD"},"validation":{"min":0},"rules":[]},{"id":"employer","type":"short_text","sectionId":"hist","label":"Current employer","required":false,"config":{},"validation":{},"rules":[]},{"id":"pets","type":"yes_no","sectionId":"hist","label":"Do you have pets?","required":true,"config":{},"validation":{},"rules":[]},{"id":"id_doc","type":"file_upload","sectionId":"hist","label":"Upload a photo ID","required":true,"config":{},"validation":{"allowedMimeTypes":["application/pdf","image/jpeg","image/png"],"maxFileSizeMb":10,"maxFiles":1},"rules":[]}],"completionScreen":{"title":"Application received","message":"We''ll review and get back to you."}}'::jsonb),
  ('Bug report', 'Capture clear, actionable bug reports from users or testers.', 'support', true, '{"schemaVersion":1,"title":"Bug report","description":"Help us squash it \u2014 the more detail, the faster we can fix it.","layout":"classic","sections":[{"id":"s1","title":"Report","pageBreakAfter":false}],"questions":[{"id":"email","type":"email","sectionId":"s1","label":"Your email (for follow-up)","required":true,"config":{},"validation":{},"rules":[]},{"id":"severity","type":"single_choice","sectionId":"s1","label":"Severity","required":true,"config":{},"validation":{},"rules":[],"options":[{"id":"o1","label":"Minor annoyance","value":"minor"},{"id":"o2","label":"Blocks a task","value":"blocking"},{"id":"o3","label":"Critical / data loss","value":"critical"}]},{"id":"summary","type":"short_text","sectionId":"s1","label":"One-line summary","required":true,"config":{},"validation":{"maxLength":150},"rules":[]},{"id":"steps","type":"long_text","sectionId":"s1","label":"Steps to reproduce","required":true,"config":{},"validation":{},"rules":[]},{"id":"expected","type":"long_text","sectionId":"s1","label":"What did you expect to happen?","required":false,"config":{},"validation":{},"rules":[]},{"id":"screenshot","type":"image_upload","sectionId":"s1","label":"Screenshot (optional)","required":false,"config":{},"validation":{"maxFileSizeMb":10,"maxFiles":3},"rules":[]}],"completionScreen":{"title":"Thanks for the report","message":"We''ll look into it."}}'::jsonb);
